const getExpectedScale = (count) => {
    if (count <= 100) {
        return 200;
    }
    if (count <= 1000) {
        return Math.ceil(count * 1.25);
    }
    if (count <= 5000) {
        return Math.ceil(count * 1.5);
    }
    return Math.ceil(count * 1.75);
};
